CREATE TABLE IF NOT EXISTS booking_service_rooms (service_id BIGINT PRIMARY KEY, booking_room_id BIGINT NOT NULL, FOREIGN KEY (service_id) REFERENCES booking_services(id), FOREIGN KEY (booking_room_id) REFERENCES booking_rooms(id));
SET @service_link_copy = (SELECT IF(COUNT(*) > 0, 'INSERT IGNORE INTO booking_service_rooms (service_id, booking_room_id) SELECT id, booking_room_id FROM booking_services WHERE booking_room_id IS NOT NULL', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='booking_services' AND column_name='booking_room_id');
PREPARE service_link_copy_stmt FROM @service_link_copy;
EXECUTE service_link_copy_stmt;
DEALLOCATE PREPARE service_link_copy_stmt;
SET @service_link_verify_query = (SELECT IF(COUNT(*) > 0, 'SELECT COUNT(*) INTO @service_link_conflicts FROM booking_services s LEFT JOIN booking_service_rooms l ON l.service_id=s.id WHERE (s.booking_room_id IS NOT NULL AND (l.service_id IS NULL OR l.booking_room_id<>s.booking_room_id)) OR (s.booking_room_id IS NULL AND l.service_id IS NOT NULL)', 'SET @service_link_conflicts=0') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='booking_services' AND column_name='booking_room_id');
PREPARE service_link_verify_stmt FROM @service_link_verify_query;
EXECUTE service_link_verify_stmt;
DEALLOCATE PREPARE service_link_verify_stmt;
SET @service_link_check = IF(@service_link_conflicts=0, 'SELECT 1', 'SELECT * FROM migration_006_service_link_conflict_requires_manual_review');
PREPARE service_link_check_stmt FROM @service_link_check;
EXECUTE service_link_check_stmt;
DEALLOCATE PREPARE service_link_check_stmt;
SELECT COUNT(*) INTO @service_link_mismatch FROM booking_service_rooms l JOIN booking_services s ON s.id=l.service_id JOIN booking_rooms r ON r.id=l.booking_room_id WHERE s.booking_id<>r.booking_id;
SET @service_link_consistency_check = IF(@service_link_mismatch=0, 'SELECT 1', 'SELECT * FROM migration_006_service_booking_mismatch_requires_manual_review');
PREPARE service_link_consistency_stmt FROM @service_link_consistency_check;
EXECUTE service_link_consistency_stmt;
DEALLOCATE PREPARE service_link_consistency_stmt;
CREATE TRIGGER IF NOT EXISTS service_room_validate_insert BEFORE INSERT ON booking_service_rooms FOR EACH ROW BEGIN DECLARE service_booking BIGINT DEFAULT NULL; DECLARE room_booking BIGINT DEFAULT NULL; SELECT booking_id INTO service_booking FROM booking_services WHERE id=NEW.service_id FOR UPDATE; SELECT booking_id INTO room_booking FROM booking_rooms WHERE id=NEW.booking_room_id FOR UPDATE; IF service_booking IS NULL OR room_booking IS NULL OR service_booking<>room_booking THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='service and room booking mismatch'; END IF; END;
CREATE TRIGGER IF NOT EXISTS service_room_validate_update BEFORE UPDATE ON booking_service_rooms FOR EACH ROW BEGIN DECLARE service_booking BIGINT DEFAULT NULL; DECLARE room_booking BIGINT DEFAULT NULL; SELECT booking_id INTO service_booking FROM booking_services WHERE id=NEW.service_id FOR UPDATE; SELECT booking_id INTO room_booking FROM booking_rooms WHERE id=NEW.booking_room_id FOR UPDATE; IF service_booking IS NULL OR room_booking IS NULL OR service_booking<>room_booking THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='service and room booking mismatch'; END IF; END;
CREATE TRIGGER IF NOT EXISTS service_booking_immutable BEFORE UPDATE ON booking_services FOR EACH ROW BEGIN DECLARE link_count BIGINT DEFAULT 0; IF OLD.booking_id<>NEW.booking_id THEN SELECT COUNT(*) INTO link_count FROM booking_service_rooms l WHERE l.service_id=OLD.id FOR UPDATE; IF link_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='linked service booking cannot change'; END IF; END IF; END;
CREATE TRIGGER IF NOT EXISTS room_booking_immutable BEFORE UPDATE ON booking_rooms FOR EACH ROW BEGIN DECLARE link_count BIGINT DEFAULT 0; IF OLD.booking_id<>NEW.booking_id THEN SELECT COUNT(*) INTO link_count FROM booking_service_rooms l WHERE l.booking_room_id=OLD.id FOR UPDATE; IF link_count>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='linked room booking cannot change'; END IF; END IF; END;
SET @service_link_drop = (SELECT IF(COUNT(*) > 0, 'ALTER TABLE booking_services DROP FOREIGN KEY service_room_booking_fk, DROP FOREIGN KEY booking_services_room_fk, DROP COLUMN booking_room_id', 'SELECT 1') FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='booking_services' AND column_name='booking_room_id');
PREPARE service_link_drop_stmt FROM @service_link_drop;
EXECUTE service_link_drop_stmt;
DEALLOCATE PREPARE service_link_drop_stmt;
